#include "frame_input.h"
#include <cstdio>
#include <chrono>
int main(){vr::EVRInitError e;vr::VR_Init(&e,vr::VRApplication_Utility);if(e)return 1;FrameInput f;for(int r=1;r<=2;r++){auto start=std::chrono::steady_clock::now();if(!f.prepare(r))return 2;auto& h=f.hands[r-1];float worst=0;int count=0;vr::RenderModel_ControllerMode_State_t mode{};for(int iy=-10;iy<=10;iy++)for(int ix=-10;ix<=10;ix++){float x=ix*.097f,y=iy*.097f;vr::VRControllerState_t raw{};raw.rAxis[0]={x,y};vr::RenderModel_ComponentState_t c{};if(!vr::VRRenderModels()->GetComponentState(h.model.c_str(),"thumbstick",&raw,&mode,&c))return 3;float dx=0,dy=0;if(!FrameInput::decode(h.stick,c.mTrackingToComponentRenderModel,dx,dy))return 4;worst=std::max(worst,std::max(std::abs(dx-x),std::abs(dy-y)));count++;}printf("hand %d %d driver pose checks; worst axis error %.4f; initialization+checks %.1fms\n",r,count,worst,std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());if(worst>.051f)return 5;}vr::VR_Shutdown();}
